import java.util.Scanner;

public class Main {
    static final int MAXN = 32;
    static final int MOD = 1000000007;

    static class Matrix {
        int N;
        int[][] a = new int[MAXN][MAXN];

        void init(int _N, int _V) {
            N = _N;
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < N; j++) {
                    a[i][j] = _V;
                }
            }
        }

        void multiply(Matrix b) {
            int[][] temp = new int[N][N];
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < N; j++) {
                    long t = 0;
                    for (int k = 0; k < N; k++) {
                        t += (long) a[i][k] * b.a[k][j];
                    }
                    temp[i][j] = (int) (t % MOD);
                }
            }
            for (int i = 0; i < N; i++) {
                System.arraycopy(temp[i], 0, a[i], 0, N);
            }
        }
    }

    static Matrix[][] A = new Matrix[64][32];
    static Matrix[][] prefix = new Matrix[64][32];
    static Matrix[][] suffix = new Matrix[64][32];

    static long n;
    static int k;

    static void precompute(int i) {
        prefix[i][1] = A[i][0];
        for (int j = 2; j <= k; j++) {
            prefix[i][j] = new Matrix();
            prefix[i][j].init(k + 1, 0);
            System.arraycopy(prefix[i][j - 1].a, 0, prefix[i][j].a, 0, MAXN * MAXN);
            prefix[i][j].multiply(A[i][j - 1]);
        }
        suffix[i][k - 1] = A[i][k - 1];
        for (int j = k - 2; j >= 0; j--) {
            suffix[i][j] = new Matrix();
            suffix[i][j].init(k + 1, 0);
            System.arraycopy(A[i][j].a, 0, suffix[i][j].a, 0, MAXN * MAXN);
            suffix[i][j].multiply(suffix[i][j + 1]);
        }
    }

    static int digitSum(long num) {
        int sum = 0;
        while (num > 0) {
            sum = (sum + (int) (num % k)) % k;
            num /= k;
        }
        return sum;
    }

    static Matrix compute(long num, int m) {
        if (num < k) {
            Matrix result = new Matrix();
            result.init(k + 1, 0);
            System.arraycopy(A[m][0].a, 0, result.a, 0, MAXN * MAXN);
            for (int i = 1; i < num; i++) {
                result.multiply(A[m][i]);
            }
            return result;
        }
        Matrix res = compute(num / k, m + 1);
        int x = digitSum(num / k);
        for (int i = 0; i < num % k; i++) {
            res.multiply(A[m][(x + i) % k]);
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextLong();
        k = sc.nextInt();

        for (int i = 0; i < k; i++) {
            for (int m = 0; m < 64; m++) {
                A[m][i] = new Matrix();
                A[m][i].init(k + 1, 0);
            }
            for (int j = 0; j <= k; j++) {
                A[0][i].a[j][j] = 1;
                A[0][i].a[j][i] = 1;
            }
        }

        int m = 1;
        while (Math.pow(k, m) - 1000 <= n) {
            precompute(m - 1);
            for (int x = 0; x < k; x++) {
                A[m][x] = new Matrix();
                A[m][x].init(k + 1, 0);
                System.arraycopy(suffix[m - 1][x].a, 0, A[m][x].a, 0, MAXN * MAXN);
                if (x > 0) {
                    A[m][x].multiply(prefix[m - 1][x]);
                }
            }
            m++;
        }

        Matrix result = compute(n, 0);
        int answer = 0;
        for (int i = 0; i <= k; i++) {
            answer = (answer + result.a[k][i]) % MOD;
        }
        System.out.println(answer);
        sc.close();
    }
}
